namespace ghidra.app.plugin.core.decompile.actions;

using docking.action;
using ghidra.app.decompiler;
using ghidra.app.plugin.core.decompile;
using ghidra.app.util;
using ghidra.program.model.listing;
using ghidra.program.model.pcode;
using ghidra.program.model.symbol;
using ghidra.util;
using ghidra.util;

public class IsolateVariableAction : AbstractDecompilerAction {

	public IsolateVariableAction() : base("Split Out As New Variable")
    {
		setHelpLocation(new HelpLocation(HelpTopics.DECOMPILER, "ActionIsolate"));
		setPopupMenuData(new MenuData(new string[] { "Split Out As New Variable" }, "Decompile"));
	}

	/* @Override */
	protected bool isEnabledForDecompilerContext(DecompilerActionContext context) {
		Function function = context.getFunction();
		if (function == null || function is UndefinedFunction) {
			return false;
		}

		ClangToken tokenAtCursor = context.getTokenAtCursor();
		if (tokenAtCursor == null) {
			return false;
		}
		HighVariable variable = tokenAtCursor.getHighVariable();
		if (!(variable is HighLocal)) {
			return false;
		}
		HighSymbol highSymbol = variable.getSymbol();
		if (highSymbol == null) {
			return false;
		}
		if (highSymbol.isIsolated()) {
			return false;
		}

		Varnode vn = tokenAtCursor.getVarnode();
		if (vn == null) {
			return false;
		}
		short mergeGroup = vn.getMergeGroup();
		bool mergeSplit = false;
		foreach (Varnode var in variable.getInstances()) {
			if (var.getMergeGroup() != mergeGroup) {
				mergeSplit = true;
				break;
			}
		}
		if (!mergeSplit) {
			return false;
		}
		return true;
	}

	/* @Override */
	protected void decompilerActionPerformed(DecompilerActionContext context) {
		ClangToken tokenAtCursor = context.getTokenAtCursor();
		HighSymbol highSymbol = tokenAtCursor.getHighVariable().getSymbol();
		IsolateVariableTask newVariableTask =
			new IsolateVariableTask(context.getTool(), context.getProgram(),
				context.getComponentProvider(), tokenAtCursor, highSymbol, SourceType.USER_DEFINED);

		newVariableTask.runTask(false);
	}

}
